import {TROUBLESHOOTING,REPAIR_SOURCES,LEVELS} from './troubleshooting-data.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function filterIssues(instrument,{query='',level='all'}={}){const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);return (TROUBLESHOOTING[instrument]||[]).filter(c=>(level==='all'||c.level===level)&&words.every(w=>[c.title,c.cause,c.student,c.teacher,c.repair,c.avoid].join(' ').toLowerCase().includes(w)))}
export function issueMarkup(card){const level=LEVELS[card.level];return `<article class="repair-card"><div class="repair-card-heading"><span class="repair-badge ${card.level}">${level.label}</span><h2>${escape(card.title)}</h2><p>${escape(card.cause)}</p></div><dl class="repair-steps"><div><dt><span class="role-dot student" aria-hidden="true"></span>Can I try it?</dt><dd>${escape(card.student)}</dd></div><div><dt><span class="role-dot teacher" aria-hidden="true"></span>Can my teacher help?</dt><dd>${escape(card.teacher)}</dd></div><div><dt><span class="role-dot shop" aria-hidden="true"></span>Does it need a shop?</dt><dd>${escape(card.repair)}</dd></div></dl><p class="repair-avoid"><strong>Take care:</strong> ${escape(card.avoid)}</p><details class="repair-references"><summary>Care references</summary><ul>${card.sources.map(id=>{const [label,url]=REPAIR_SOURCES[id];return `<li><a href="${url}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a></li>`}).join('')}</ul></details></article>`}
export class InstrumentTroubleshooter {
 constructor(root){this.root=root;this.instrument=null;this.level='all';this.query='';this.input=root.querySelector('#repair-search');this.grid=root.querySelector('#repair-grid');this.input.addEventListener('input',e=>{this.query=e.target.value;this.render()});root.querySelector('#repair-filter').addEventListener('change',e=>{this.level=e.target.value;this.render()});root.querySelector('#repair-reset').addEventListener('click',()=>{this.reset();this.render();this.input.focus()})}
 reset(){this.level='all';this.query='';this.input.value='';this.root.querySelector('#repair-filter').value='all'}
 show(instrument){if(this.instrument?.id!==instrument.id){this.reset();this.instrument=instrument}this.root.querySelector('#repair-title').textContent=instrument.name+' troubleshooting';this.input.placeholder=instrument.id==='bells'?'Try “bar,” “stand,” or “rattle”…':'Try “stuck,” “air,” or “loose”…';this.render()}
 render(){if(!this.instrument)return;const cards=filterIssues(this.instrument.id,{query:this.query,level:this.level});this.grid.innerHTML=cards.length?cards.map(issueMarkup).join(''):'<div class="repair-empty"><h2>No matching problems.</h2><p>Try a shorter search, show all problems, or ask your teacher to take a look.</p></div>';this.root.querySelector('#repair-count').textContent=`${cards.length} of ${TROUBLESHOOTING[this.instrument.id].length} problems`;this.root.querySelector('#repair-reset').disabled=!this.query&&this.level==='all'}
}
